package com.bank.interest;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.logging.*;

public class SolidDemo {
    private static final Logger log = Logger.getLogger(SolidDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // DIP: register strategies behind the abstraction, keyed by type.
        Map<String, InterestStrategy> strategies = new HashMap<>();
        strategies.put("SAVINGS", new SavingsInterest());
        strategies.put("CURRENT", new CurrentInterest());
        strategies.put("FIXED_DEPOSIT", new FixedDepositInterest());

        InterestCalculator calc = new InterestCalculator(strategies);

        Account rajesh = new Account("SAV2001", "Rajesh", "SAVINGS", new BigDecimal("1000000"));
        Account rajeshFd = new Account("FD4001", "Rajesh", "FIXED_DEPOSIT", new BigDecimal("500000"));

        log.info("=== SOLID interest calculation ===");
        calc.applyInterest(rajesh);
        calc.applyInterest(rajeshFd);

        // OCP demonstration: a NEW account type = a NEW class, zero edits above.
        strategies.put("NRE", new InterestStrategy() {
            public BigDecimal interest(BigDecimal bal) { return bal.multiply(new BigDecimal("0.06")); }
            public String name() { return "NRE 6%"; }
        });
        Account priyaNre = new Account("NRE5001", "Priya", "NRE", new BigDecimal("250000"));
        calc.applyInterest(priyaNre);
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private final String type;
    private BigDecimal balance;
    Account(String id, String name, String type, BigDecimal bal) {
            this.accountId = id;
            this.holderName = name
            this.type = type
            this.balance = bal;
    }
    String getAccountId() { return accountId; }
    String getType() { return type; }
    BigDecimal getBalance() { return balance; }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
}

// ─── Would be in strategy/InterestStrategy.java ───
// Small, focused interface (ISP). Abstraction for DIP and OCP.
interface InterestStrategy {
    BigDecimal interest(BigDecimal balance);
    String name();
}

// ─── Would be in strategy/SavingsInterest.java ───
class SavingsInterest implements InterestStrategy {
    public BigDecimal interest(BigDecimal bal) { return bal.multiply(new BigDecimal("0.04")); }
    public String name() { return "Savings 4%"; }
}

// ─── Would be in strategy/CurrentInterest.java ───
class CurrentInterest implements InterestStrategy {
    public BigDecimal interest(BigDecimal bal) { return BigDecimal.ZERO; } // current earns none
    public String name() { return "Current 0%"; }
}

// ─── Would be in strategy/FixedDepositInterest.java ───
class FixedDepositInterest implements InterestStrategy {
    public BigDecimal interest(BigDecimal bal) { return bal.multiply(new BigDecimal("0.075")); }
    public String name() { return "Fixed Deposit 7.5%"; }
}

// ─── Would be in service/InterestCalculator.java ───
// SRP: its ONLY job is to pick and apply the right strategy.
// DIP: it depends on the InterestStrategy abstraction, never a concrete class.
class InterestCalculator {
    private static final Logger log = Logger.getLogger(InterestCalculator.class.getName());
    private final Map<String, InterestStrategy> strategies;

    InterestCalculator(Map<String, InterestStrategy> strategies) {
        this.strategies = strategies;
    }

    void applyInterest(Account account) {
        InterestStrategy strategy = strategies.get(account.getType());
        if (strategy == null) {
            log.severe(() -> "No interest strategy for type " + account.getType());
            return;
        }
        BigDecimal interest = strategy.interest(account.getBalance()).setScale(2, RoundingMode.HALF_UP);
        account.credit(interest);
        log.info(() -> account.getAccountId() + " (" + strategy.name() + "): +Rs." + interest
                + " -> new balance Rs." + account.getBalance());
    }
}

